import {sphereMesh,rotatePoint,pickGlobe,clamp} from './globe-engine.js?v=10';
export function shaderProgram(gl,vertex,fragment){const compile=(type,code)=>{const s=gl.createShader(type);gl.shaderSource(s,code);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;};const p=gl.createProgram();gl.attachShader(p,compile(gl.VERTEX_SHADER,vertex));gl.attachShader(p,compile(gl.FRAGMENT_SHADER,fragment));gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(p));return p;}
export function attribute(gl,p,name,data,size){const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,data,gl.STATIC_DRAW);const a=gl.getAttribLocation(p,name);gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,size,gl.FLOAT,false,0,0);return b;}
export function makeGlobe(canvas){let gl;try{gl=canvas.getContext('webgl',{alpha:true,antialias:true});}catch{}if(!gl)return null;
 const p=shaderProgram(gl,`attribute vec3 position;attribute vec2 uv;uniform vec2 rotation;uniform vec2 scale;varying vec2 vUV;varying vec3 normal;void main(){float c=cos(rotation.x),s=sin(rotation.x);vec3 n=vec3(c*position.x+s*position.z,position.y,-s*position.x+c*position.z);c=cos(rotation.y);s=sin(rotation.y);n=vec3(n.x,c*n.y-s*n.z,s*n.y+c*n.z);normal=n;vUV=uv;gl_Position=vec4(n.xy*scale,-n.z*.5,1.);}`,`precision mediump float;uniform sampler2D map;varying vec2 vUV;varying vec3 normal;void main(){vec3 col=texture2D(map,vUV).rgb;float light=.3+.7*max(0.,dot(normalize(normal),normalize(vec3(-.5,.5,1.))));float rim=pow(1.-max(0.,normal.z),3.);gl_FragColor=vec4(col*light+vec3(.24,.13,.14)*rim,1.);}`);
 gl.useProgram(p);const mesh=sphereMesh();attribute(gl,p,'position',mesh.positions,3);attribute(gl,p,'uv',mesh.uv,2);const ib=gl.createBuffer();gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,ib);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,mesh.indices,gl.STATIC_DRAW);
 const texture=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,texture);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,1,1,0,gl.RGBA,gl.UNSIGNED_BYTE,new Uint8Array([183,111,91,255]));gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
 const image=new Image();image.onload=()=>{gl.bindTexture(gl.TEXTURE_2D,texture);gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,true);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,image);};image.src='./assets/mars-viking.jpg';
 const state={yaw:-137.8*Math.PI/180,pitch:0,zoom:.55};
 function draw(){const w=canvas.clientWidth,h=canvas.clientHeight,dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}gl.viewport(0,0,canvas.width,canvas.height);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.enable(gl.DEPTH_TEST);gl.useProgram(p);gl.uniform2f(gl.getUniformLocation(p,'rotation'),state.yaw,state.pitch);gl.uniform2f(gl.getUniformLocation(p,'scale'),Math.min(w,h)/w*1.52*state.zoom,Math.min(w,h)/h*1.52*state.zoom);gl.drawElements(gl.TRIANGLES,mesh.indices.length,gl.UNSIGNED_SHORT,0);}
 function pick(x,y){const r=Math.min(canvas.clientWidth,canvas.clientHeight)*.76*state.zoom;return pickGlobe((x-canvas.clientWidth/2)/r,(canvas.clientHeight/2-y)/r,state.yaw,state.pitch);}
 function project(lat,lon){const p=rotatePoint(lat,lon,state.yaw,state.pitch),r=Math.min(canvas.clientWidth,canvas.clientHeight)*.76*state.zoom;return{x:canvas.clientWidth/2+p.x*r,y:canvas.clientHeight/2-p.y*r,visible:p.z>.12};}
 return {state,draw,pick,project,turn(dx,dy){state.yaw+=dx;state.pitch=clamp(state.pitch+dy,-1.4,1.4);},zoom(d){state.zoom=clamp(state.zoom+d,.35,.86);}};
}
